    print(f"Page {page}: {len(transactions_page)} transactions")

    for t in transactions_page:
        created = datetime.fromisoformat(t.get('created_at', '').replace('Z', '+00:00')).date()
        desc = t.get('description', '').lower()
        if 'azure' in desc or 'harbor' in desc or 'bistro' in desc:
            print(f"  FOUND! Date: {created}, Description: {t.get('description')}, Sender: {t.get('sender', {}).get('name')}, Receiver: {t.get('receiver', {}).get('name')}, Amount: ${t.get('amount')}")

# Continue checking more pages for Azure Harbor Bistro
for page in range(2, 10):
    transactions_page = apis.venmo.show_transactions(access_token=token, page_index=page)
    if not transactions_page:
        print(f"No more transactions at page {page}")
        break

    azure_found = False
    for t in transactions_page:
        if 'azure harbor' in t.get('description', '').lower():
            created = datetime.fromisoformat(t.get('created_at', '').replace('Z', '+00:00')).date()
