            print(f"  Sender: {t.get('sender', {}).get('name')}, Receiver: {t.get('receiver', {}).get('name')}")
            azure_found = True

    if not azure_found and page <= 5:
        print(f"Page {page}: {len(transactions_page)} transactions, no Azure Harbor found")

