action.code:
# Get creation dates for all files
files_info = []
for file_path in files_list:
    file_details = apis.file_system.show_file(access_token=token, file_path=file_path)
    files_info.append({
        'path': file_path,
        'created_at': file_details['created_at'],
        'filename': file_path.split('/')[-1]
    })

# Show first few with dates
for info in files_info[:5]:
    print(f"{info['filename']} -> {info['created_at']}")

# Get creation dates for all files
file_details = []
for file_path in files_list:
    try:
        details = apis.file_system.show_file(access_token=token, file_path=file_path)
        file_details.append(details)
    except Exception as e:
        print(f"Error getting details for {file_path}: {e}")

print(f"Retrieved details for {len(file_details)} files")
print("Sample file details:")
for detail in file_details[:3]:
    print(f"  {detail['path'].split('/')[-1]} - created: {detail['created_at']}")

# Get creation dates for all files
file_details = []
for file_path in files_list:
    file_info = apis.file_system.show_file(access_token=token, file_path=file_path)
    file_details.append({
        'path': file_path,
        'created_at': file_info['created_at'],
        'filename': file_path.split('/')[-1]
    })

# Show first 5 with dates
for f in file_details[:5]:
    print(f"{f['filename']}: {f['created_at']}")

