action.code:
from datetime import datetime, timedelta

current_time = datetime.fromisoformat('2023-05-18T11:58:00')
threshold_days = 40

pending_requests = []

for req in sent_requests:
    if req['approved_at'] is None and req['denied_at'] is None:
        created_at = datetime.fromisoformat(req['created_at'])
        days_old = (current_time - created_at).days
        if days_old >= threshold_days:
            pending_requests.append({
                'payment_request_id': req['payment_request_id'],
                'days_old': days_old,
                'receiver_name': req['receiver']['name'],
                'receiver_email': req['receiver']['email'],
                'amount': req['amount'],
                'description': req['description']
            })

print(f"Payment requests pending for 40+ days:")
for req in pending_requests:
    print(f"ID: {req['payment_request_id']}, Days: {req['days_old']}, Receiver: {req['receiver_name']}, Amount: ${req['amount']}")

# Let me check all pending requests and their ages
for req in sent_requests:
    if req['approved_at'] is None and req['denied_at'] is None:
        created_time = datetime.fromisoformat(req['created_at'])
        days_elapsed = (current_time - created_time).days
        print(f"ID: {req['payment_request_id']}, Days: {days_elapsed}, Receiver: {req['receiver']['name']}, Created: {req['created_at']}")

