# Get all playlists
all_playlist_songs = set()
page_index = 0
while True:
    result = apis.spotify.show_playlist_library(access_token=token, page_index=page_index)
    if not result:
        break
    for playlist in result:
        playlist_id = playlist['playlist_id']
        # Get songs in each playlist
        playlist_songs_page = 0
        while True:
            playlist_details = apis.spotify.show_playlist(access_token=token, playlist_id=playlist_id, page_index=playlist_songs_page)
            if not playlist_details['songs']:
                break
            for song in playlist_details['songs']:
                all_playlist_songs.add(song['id'])
            playlist_songs_page += 1
    page_index += 1

print(f"Songs from playlists: {len(all_playlist_songs)}")

